import json,hashlib,numpy as np
from pathlib import Path
R=Path(__file__).resolve().parent; I=R.parent.parent/'inputs/M4';p=json.load(open(I/'packet.json'))
def ray(i,u,v,axis,value):
 T=np.array(p['frames'][i]['camera_to_world']);d=T[:3,:3]@np.linalg.solve(np.array(p['intrinsics']),[u,v,1]);return (T[:3,3]+d*(value-T[axis,3])/d[axis]).tolist()
